def hidden_rule_fn(state):
    rows = len(state)
    cols = len(state[0])
    next_state = [[0]*cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            ne = state[(r-1) % rows][(c+1) % cols]
            nw = state[(r-1) % rows][(c-1) % cols]
            se = state[(r+1) % rows][(c+1) % cols]
            sw = state[(r+1) % rows][(c-1) % cols]

            vals = [ne, nw, se, sw]
            d_z = vals.count(0)
            d_p = vals.count(1)
            d_q = vals.count(2)
            cur = state[r][c]

            # Determine next state based on diagonal counts and current value
            key = (d_z, d_p, d_q, cur)

            # Lookup table based on observed patterns
            if key == (3, 1, 0, 2):
                nxt = 1
            elif key == (1, 1, 2, 0):
                nxt = 0
            elif key == (1, 1, 2, 2):
                nxt = 2
            elif key == (2, 0, 2, 0):
                nxt = 0
            elif key == (2, 0, 2, 1):
                nxt = 1
            elif key == (2, 0, 2, 2):
                nxt = 1
            elif key == (1, 0, 3, 0):
                nxt = 2
            elif key == (1, 0, 3, 1):
                nxt = 1
            elif key == (3, 0, 1, 0):
                nxt = 0
            elif key == (3, 0, 1, 1):
                nxt = 1
            elif key == (3, 0, 1, 2):
                nxt = 1
            elif key == (2, 1, 1, 1):
                nxt = 2
            elif key == (2, 1, 1, 2):
                nxt = 1
            elif key == (0, 1, 3, 1):
                nxt = 2
            elif key == (0, 1, 3, 2):
                nxt = 2
            elif key == (1, 2, 1, 1):
                nxt = 1
            else:
                # Fallback: use formula (d_p + 2*d_z) % 3
                nxt = (d_p + 2 * d_z) % 3

            next_state[r][c] = nxt

    return next_state
